from collections import deque


def clip_recall(highlights, clips):
    """
    Return the fraction of highlights found by the clips.

    A clip can find a highlight only if they share more than zero seconds.
    Touching endpoints do not count. Each clip can be credited to at most one
    highlight, and the score credits as many highlights as possible
    (a maximum bipartite matching found with Hopcroft-Karp).

    highlights, clips: lists of (start_s, end_s) tuples.
    """
    n_h = len(highlights)
    if n_h == 0:
        raise ValueError("highlights must contain at least one interval")

    # Build edges: highlight i -> clip j when they overlap by a positive amount.
    adj = []
    for h_start, h_end in highlights:
        neighbors = [
            j for j, (c_start, c_end) in enumerate(clips)
            if max(h_start, c_start) < min(h_end, c_end)
        ]
        adj.append(neighbors)

    INF = float("inf")
    match_h = [-1] * n_h          # highlight -> clip
    match_c = [-1] * len(clips)   # clip -> highlight
    dist = [INF] * n_h

    def bfs():
        queue = deque()
        for h in range(n_h):
            if match_h[h] == -1:
                dist[h] = 0
                queue.append(h)
            else:
                dist[h] = INF
        found_free = False
        while queue:
            h = queue.popleft()
            for c in adj[h]:
                w = match_c[c]
                if w == -1:
                    found_free = True
                elif dist[w] == INF:
                    dist[w] = dist[h] + 1
                    queue.append(w)
        return found_free

    def dfs(root, it):
        # Iterative DFS for an augmenting path starting at a free highlight.
        stack = [root]
        chosen = []  # chosen[i] is the clip used to step from stack[i] onward
        while stack:
            v = stack[-1]
            if it[v] < len(adj[v]):
                c = adj[v][it[v]]
                it[v] += 1
                w = match_c[c]
                if w == -1:
                    chosen.append(c)
                    for h, clip in zip(stack, chosen):
                        match_h[h] = clip
                        match_c[clip] = h
                    return True
                if dist[w] == dist[v] + 1:
                    stack.append(w)
                    chosen.append(c)
            else:
                dist[v] = INF
                stack.pop()
                if chosen:
                    chosen.pop()
        return False

    matched = 0
    while bfs():
        it = [0] * n_h
        for h in range(n_h):
            if match_h[h] == -1 and dfs(h, it):
                matched += 1

    return matched / n_h
